-- GUS-242 step 1f — vocabularies.
--
-- Families, techniques and contexts, grown to the sizes the
-- GUS-242 plan set, with a parent_id hierarchy on the families.
--
-- Generated by scripts/build_vocab_1f.py + scripts/emit_vocab_1f_sql.py
-- from a single source of truth, so the row set and the assertions
-- cannot drift apart.
--
-- Run inside a transaction with the count assertions FIRST (RULES.md §3).
--
-- Usage:
--   psql -v ON_ERROR_STOP=1 -d <db> -f packages/db/drizzle/0018_gus242_vocab_1f.sql
--
-- ROLLBACK
--   DELETE FROM dish_families     WHERE slug IN (<the 168 slugs>);
--   DELETE FROM dish_techniques   WHERE slug IN (<the 63 slugs>);
--   DELETE FROM dish_contexts     WHERE slug IN (<the 26 slugs>);
--   (restore the 28 families' parent_id to NULL)

\set ON_ERROR_STOP on
-- IDEMPOTENT
--
-- Safe to re-apply: a fresh deploy applies the whole chain, and
-- the chain may be applied to a database that is already
-- migrated. The guard checks that the data is present AND that
-- this migration has not already been applied.
--
-- The "already applied" marker for 0018: the new families,
-- techniques and contexts are all present.
SELECT
  EXISTS (SELECT 1 FROM dish_families)
  AND NOT (
    (SELECT count(*) FROM dish_families
      WHERE slug IN ('beverage','thali','rijsttafel','meze','banchan',
                     'nasi-campur','flatbread','pilaf','biryani','tempura',
                     'falafel','halwa','bubbletea','hot-pot','fondue')) = 15
    AND
    (SELECT count(*) FROM dish_techniques
      WHERE slug IN ('broiling','dicing','emulsifying','griddle','laminating',
                     'resting','wok','clay-oven','sun-drying','caramelizing')) = 10
    AND
    (SELECT count(*) FROM dish_contexts
      WHERE slug IN ('tableside','street-vendor','home-cooking','banquet',
                     'buffet','picnic','camping','school-meal','hospitality',
                     'festive','fasting','breakfast','lunch','dinner','supper',
                     'snack','dessert-course','appetizer','condiment-course',
                     'preserved','emergency-ration','travel-food','funeral',
                     'temple-offering','military','workplace')) = 26
  ) AS have_data \gset
\if :have_data
\echo 'GUS-242: the seeded data is present and this migration is not yet applied - running it'



-- =====================================================================

\else
\echo 'GUS-242: the seeded data is NOT present, or this migration is already applied - skipping it'
\endif
